// #bdd327 (6a993d6887e898ed58bdd327) «פיתוח: מכסת סימולציות ומעקב צריכה» — состояния квоты через ПОДМЕНУ ответа get_business_usage (route.fulfill).
// Кейсы QUOTA-005…QUOTA-008. Сервер и квота testim не меняются; create_candidate обрывается и должен быть вызван 0 раз; «אישור והמשך» НЕ нажимается.
// Роли: менеджер аккаунта testim (auth/bizt.json), מנהל/ת מגייס/ת testim (auth/user-2.json). Только десктоп (L-20261014-5).
import { test, expect } from '@playwright/test';
import { HASH, MANAGER_STATE, RECRUITER_STATE, usageBody, mockUsage, blockCandidateCreation, openInviteDrawer, footerLine } from './support';

test.describe(`Квота — предупреждение о пороге, дашборд менеджера аккаунта, подмена usage (${HASH})`, () => {
  test.use({ storageState: MANAGER_STATE });

  test(`QUOTA-005: использовано 4 из 5 (порог 80%) → «מתקרבים למכסה: נותרה סימולציה אחת מתוך 5» + пояснение про подтверждение превышения; строка «נוצלו 4 מתוך 5 · נותרה 1» @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await mockUsage(page, usageBody({ used: 4, quota: 5, remaining: 1 }));
    await page.goto('/');

    // Источник: AC3 «менеджеру при входе показывается предупреждение о приближении к квоте»; факт 17.11 (bdd327-bizt-dashboard-threshold-80pct).
    await expect(page.getByText('מתקרבים למכסה: נותרה סימולציה אחת מתוך 5')).toBeVisible();
    await expect(page.getByText(/אפשר להמשיך להזמין גם אחרי 5\s.\s+כל הזמנה מעבר למכסה תדרוש אישור מפורש ותירשם לחיוב/)).toBeVisible();
    // Требование 4: потребление на дашборде.
    await expect(page.getByText('מכסת סימולציות', { exact: true }).first()).toBeVisible();
    await expect(page.getByText(/נוצלו\s+4\s+מתוך\s+5/).first()).toBeVisible();
    await expect(page.getByText(/נותר[הו]\s+1(?!\d)/).first()).toBeVisible();
  });

  test(`QUOTA-006: использовано 1 из 5 (ниже порога 80%) → предупреждения «מתקרבים למכסה» нет, строка «נוצלו 1 מתוך 5» есть @desktop @prod-safe ${HASH}`, async ({ page }) => {
    await mockUsage(page, usageBody({ used: 1, quota: 5, remaining: 4 }));
    await page.goto('/');

    // Источник: AC3 — предупреждение только после пересечения порога.
    await expect(page.getByText(/נוצלו\s+1\s+מתוך\s+5/).first()).toBeVisible();
    await expect(page.getByText(/מתקרבים למכסה/)).toHaveCount(0);
  });
});

for (const r of [
  { id: 'QUOTA-007', who: 'менеджер аккаунта', state: MANAGER_STATE },
  { id: 'QUOTA-008', who: 'מנהל/ת מגייס/ת', state: RECRUITER_STATE },
]) {
  test.describe(`Квота исчерпана — drawer «מועמד חדש» и окно превышения, ${r.who}, подмена usage (${HASH})`, () => {
    test.use({ storageState: r.state });

    test(`${r.id}: квота 4, использовано 4 → «נותרו 0 מתוך 4», окно «המכסה של התקופה נוצלה» (מכסה לתקופה 4, הושלמו 4, חריגה של 1), чекбокс «אני מאשר/ת חריגה…», «אישור והמשך» / «חזרה בלי להזמין»; кандидат не создаётся @desktop @prod-safe ${HASH}`, async ({ page }) => {
      await mockUsage(page, usageBody({ used: 4, quota: 4, remaining: 0 }));
      const created = await blockCandidateCreation(page);
      await page.goto('/candidates');
      await openInviteDrawer(page);

      // Источник: AC4 «сообщение о превышении, приглашение возможно только после явного подтверждения»; решение реализатора 05.11 — окно открывается при входе в обеих ролях.
      await expect(page.getByText('המכסה של התקופה נוצלה', { exact: true })).toBeVisible();
      await expect(page.getByText('מכסה לתקופה', { exact: true })).toBeVisible();
      await expect(page.getByText('הושלמו', { exact: true })).toBeVisible();
      await expect(page.getByText('אחרי ההזמנה הזו', { exact: true })).toBeVisible();
      await expect(page.getByText('חריגה של 1', { exact: true })).toBeVisible();
      await expect(page.getByText(/האישור נרשם לחיוב עם שמך ומועד האישור/)).toBeVisible();

      const confirm = page.getByRole('checkbox', { name: /אני מאשר\/ת חריגה מהמכסה עבור ההזמנה הזו/ });
      await expect(confirm).toBeVisible();
      await expect(confirm).not.toBeChecked();
      await expect(page.getByRole('button', { name: 'אישור והמשך' })).toBeVisible();
      await expect(page.getByRole('button', { name: 'חזרה בלי להזמין' })).toBeVisible();

      // Футер drawer под окном: «נותרו 0 מתוך 4».
      await expect(footerLine(page)).toHaveText(/^נותרו\s+0\s+מתוך\s+4$/);

      // Явное подтверждение отмечается; «אישור והמשך» не нажимаем (подтверждение превышения записывается для биллинга).
      await confirm.check();
      await expect(confirm).toBeChecked();

      // «חזרה בלי להזמין» закрывает окно, ничего не отправляя.
      await page.getByRole('button', { name: 'חזרה בלי להזמין' }).click();
      await expect(page.getByText('המכסה של התקופה נוצלה', { exact: true })).toHaveCount(0);
      expect(created(), 'create_candidate не должен вызываться').toBe(0);
    });
  });
}
